// Some portions generated by Claude
/**
 * Polyomino packing of laid-out components (Freivalds, Dogrusoz and Kikusts, "Disconnected Graph Layout and the
 * Polyomino Packing Approach", GD 2001). Each component becomes the set of grid cells its cards and links cover; the
 * components are placed largest first at the free position that keeps the whole drawing's box smallest for the wanted
 * aspect ratio, so a small component can sit in an empty corner of a large one (a fan's corners are empty).
 */
/** Grid cells across a typical component: finer packs tighter and searches longer. */
const CELLS_PER_ITEM = 20;
/** Above this many components, rows of components (shelves) are packed instead: the grid search grows too costly. */
const POLYOMINO_LIMIT = 150;

export type PackItem = {
  /** Card boxes of the component (absolute bounds). */
  boxes: Array<{minX: number; minY: number; maxX: number; maxY: number}>;
  /** Link segments between card centres. */
  segments: Array<[number, number, number, number]>;
};

/** Offsets that move each item into the packing, in item order. */
export function packComponents(items: PackItem[], aspectRatio: number, clearance: number): Array<{x: number; y: number}> {
  if (items.length <= 1) return items.map(() => ({x: 0, y: 0}));
  if (items.length > POLYOMINO_LIMIT) return packShelves(items, aspectRatio, clearance);
  let totalArea = 0;
  for (const item of items) for (const b of item.boxes) totalArea += (b.maxX - b.minX + clearance) * (b.maxY - b.minY + clearance);
  // Cells about a third of a card's height keep corners usable without making the search expensive.
  const cell = Math.max(12, Math.min(48, Math.sqrt(totalArea / Math.max(1, items.length)) / CELLS_PER_ITEM));
  const polyominoes = items.map(item => polyomino(item, cell, clearance));
  const order = items.map((_, i) => i).sort((a, b) => polyominoes[b].cells.length - polyominoes[a].cells.length || a - b);
  const occupied = new Set<number>();
  const key = (x: number, y: number) => (x + 32768) * 65536 + (y + 32768);
  const offsets: Array<{x: number; y: number}> = items.map(() => ({x: 0, y: 0}));
  let minX = 0, minY = 0, maxX = -1, maxY = -1;
  for (const index of order) {
    const p = polyominoes[index];
    let best: {dx: number; dy: number; value: number} | null = null;
    if (maxX < minX) {
      best = {dx: -p.minX, dy: -p.minY, value: 0};
    } else {
      // Candidate positions: every cell offset within the current box grown by the polyomino's size, nearest first.
      const width = p.maxX - p.minX + 1, height = p.maxY - p.minY + 1;
      const centreX = (minX + maxX) / 2, centreY = (minY + maxY) / 2;
      const candidates: Array<[number, number, number]> = [];
      for (let y = minY - height - 1; y <= maxY + 1; y++) for (let x = minX - width - 1; x <= maxX + 1; x++) {
        const cx = x + width / 2 - centreX, cy = y + height / 2 - centreY;
        candidates.push([x, y, cx * cx / aspectRatio + cy * cy * aspectRatio]);
      }
      candidates.sort((a, b) => a[2] - b[2]);
      for (const [x, y] of candidates) {
        const dx = x - p.minX, dy = y - p.minY;
        const nx0 = Math.min(minX, x), ny0 = Math.min(minY, y), nx1 = Math.max(maxX, x + width - 1), ny1 = Math.max(maxY, y + height - 1);
        const w = nx1 - nx0 + 1, h = ny1 - ny0 + 1, skew = Math.log((w / h) / aspectRatio);
        const value = w * h * (1 + 0.6 * skew * skew);
        if (best && value >= best.value) continue;
        if (p.cells.some(([cx, cy]) => occupied.has(key(cx + dx, cy + dy)))) continue;
        best = {dx, dy, value};
      }
    }
    const {dx, dy} = best!;
    for (const [cx, cy] of p.cells) occupied.add(key(cx + dx, cy + dy));
    minX = Math.min(minX, p.minX + dx); minY = Math.min(minY, p.minY + dy);
    maxX = Math.max(maxX, p.maxX + dx); maxY = Math.max(maxY, p.maxY + dy);
    offsets[index] = {x: dx * cell, y: dy * cell};
  }
  return offsets;
}

function polyomino(item: PackItem, cell: number, clearance: number) {
  const cells = new Set<number>(), list: Array<[number, number]> = [];
  const add = (x: number, y: number) => {
    const k = (x + 32768) * 65536 + (y + 32768);
    if (!cells.has(k)) { cells.add(k); list.push([x, y]); }
  };
  const half = clearance / 2;
  for (const b of item.boxes) {
    for (let y = Math.floor((b.minY - half) / cell); y <= Math.floor((b.maxY + half) / cell); y++)
      for (let x = Math.floor((b.minX - half) / cell); x <= Math.floor((b.maxX + half) / cell); x++) add(x, y);
  }
  for (const [x0, y0, x1, y1] of item.segments) {
    const steps = Math.max(1, Math.ceil(Math.hypot(x1 - x0, y1 - y0) / (cell / 2)));
    for (let s = 0; s <= steps; s++) add(Math.floor((x0 + (x1 - x0) * s / steps) / cell), Math.floor((y0 + (y1 - y0) * s / steps) / cell));
  }
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const [x, y] of list) { minX = Math.min(minX, x); minY = Math.min(minY, y); maxX = Math.max(maxX, x); maxY = Math.max(maxY, y); }
  return {cells: list, minX, minY, maxX, maxY};
}

/** Components in rows, tallest first, the rows as wide as a box of the wanted aspect ratio holding them all. */
function packShelves(items: PackItem[], aspectRatio: number, clearance: number) {
  const boxes = items.map((item, index) => {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const b of item.boxes) { minX = Math.min(minX, b.minX); minY = Math.min(minY, b.minY); maxX = Math.max(maxX, b.maxX); maxY = Math.max(maxY, b.maxY); }
    return {index, minX, minY, width: maxX - minX + clearance, height: maxY - minY + clearance};
  }).sort((a, b) => b.height - a.height || b.width - a.width || a.index - b.index);
  const area = boxes.reduce((sum, b) => sum + b.width * b.height, 0);
  const rowWidth = Math.max(Math.max(...boxes.map(b => b.width)), Math.sqrt(area * aspectRatio));
  const offsets: Array<{x: number; y: number}> = items.map(() => ({x: 0, y: 0}));
  let x = 0, y = 0, rowHeight = 0;
  for (const b of boxes) {
    if (x && x + b.width > rowWidth) { x = 0; y += rowHeight; rowHeight = 0; }
    offsets[b.index] = {x: x - b.minX, y: y - b.minY};
    x += b.width; rowHeight = Math.max(rowHeight, b.height);
  }
  return offsets;
}
